"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[14312],{1974:e=>{e.exports=JSON.parse('{"label":"rollups","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/1.0/tags/rollups","allTagsPath":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/1.0/tags","count":10,"items":[{"id":"version-1.0/assets-handling","title":"Assets handling","description":"Assets exist on the base layer, which is where they have actual meaning and value. As with any execution layer solution, a Cartesi dApp that wants to manipulate assets (e.g. to allow players to bet on a game, so that the winner receives the loser\'s assets) needs a secure way of \\"teleporting\\" the assets from the base layer to the execution layer, and then a way to \\"teleport\\" them back to the base layer.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/1.0/assets-handling"},{"id":"version-1.0/migration-guides/from-09-to-10","title":"Breaking Changes v1.0","description":"This guide is designed to highlight the key distinctions between v0.9 and v1.0, offering assistance to those transitioning an existing application or individuals already acquainted with v0.9 who require a concise overview.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/1.0/migration-guides/from-09-to-10"},{"id":"version-1.0/mainnet-risks","title":"Cartesi Rollups - Understanding the risks","description":"Cartesi Rollups is an app-specific execution environment that can be deployed as a L2, L3, or as sovereign rollups. It\'s not your typical L1 blockchain, so the idea of a \\"Mainnet launch\\" is a bit different. What actually goes to mainnet are the dApps built using Cartesi! And with the launch of the Honeypot dApp, Cartesi Rollups is officially Mainnet-ready (beta)!","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/1.0/mainnet-risks"},{"id":"version-1.0/dapp-architecture","title":"dApp architecture","description":"Borrowing from familiar mainstream terminology, from a developer\u2019s point of view a Cartesi dApp is developed by implementing two main components: a front-end and a back-end.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/1.0/dapp-architecture"},{"id":"version-1.0/dapp-life-cycle","title":"dApp life cycle","description":"Now that we have described the architecture of a Cartesi dApp and how the front-end and back-end communicate with the Cartesi Rollups framework, let\u2019s step back a bit to discuss how a dApp can be implemented in practice.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/1.0/dapp-life-cycle"},{"id":"version-1.0/main-concepts","title":"Main concepts","description":"As explained in the previous section, the Cartesi Rollups framework achieves scalability by moving the bulk of the computation outside the blockchain, using the ledger as a data source but not as an execution environment. As such, the solution contains both on-chain (L1) and off-chain (L2) components.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/1.0/main-concepts"},{"id":"version-1.0/http-api","title":"Overview","description":"In a Cartesi dApp, the front-end and back-end parts of the application communicate with each other through the Rollups framework via a set of HTTP APIs.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/1.0/http-api"},{"id":"version-1.0/overview","title":"Overview","description":"The combination of an Optimistic Rollups framework and the Cartesi Machine Emulator enables the development of smart contracts and dApps using any package or library that is available for Linux. This allows developers to break free from the scalability limitations of the Ethereum Virtual Machine (EVM), and brings the rise of a new blockchain era to handle real-life and complex use cases.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/1.0/overview"},{"id":"version-1.0/reading-outputs","title":"Reading outputs","description":"In Cartesi Rollups, the outputs include:","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/1.0/reading-outputs"},{"id":"version-1.0/sending-requests","title":"Sending requests","description":"In Cartesi Rollups, there are two kinds of requests that can be made to the dApp:","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/1.0/sending-requests"}]}')}}]);